	/**
	 * Whether a glyph exists for a key.
	 *
	 * @param string $key Icon key.
	 * @return bool
	 */
	public static function has( string $key ): bool {
		return isset( self::data()[ $key ] );
	}

	/**
	 * Brand color (#RRGGBB) or '' when unknown.
	 *
	 * @param string $key Icon key.
	 * @return string
	 */
	public static function color( string $key ): string {
		$data = self::data();

		return isset( $data[ $key ] ) && '' !== $data[ $key ][0] ? '#' . $data[ $key ][0] : '';
	}

	/**
	 * Inline SVG (decorative; the link text names the platform).
	 *
	 * @param string $key   Icon key.
	 * @param string $class Class attribute.
	 * @return string Empty string when no glyph exists.
	 */
	public static function svg( string $key, string $class = '' ): string {
		$data = self::data();

		if ( ! isset( $data[ $key ] ) ) {
			return '';
		}

		return '<svg' . ( '' !== $class ? ' class="' . esc_attr( $class ) . '"' : '' ) . ' viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false"><path d="' . esc_attr( $data[ $key ][1] ) . '"/></svg>';
	}
}
